CREATE OR REPLACE FUNCTION auth.jwt()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb)
$function$;

CREATE OR REPLACE FUNCTION auth.role()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(nullif(current_setting('request.jwt.claim.role', true), ''), 'anon')
$function$;

CREATE OR REPLACE FUNCTION auth.uid()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
$function$;

CREATE OR REPLACE FUNCTION public.alias_profiles_handle_namespace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.handle is distinct from coalesce(old.handle, null) then
    perform public.assert_handle_namespace_free(new.handle, new.user_id);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.assert_handle_namespace_free(_handle text, _user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  _h text := lower(btrim(coalesce(_handle, '')));
  _owner uuid;
begin
  if _h = '' then
    return;
  end if;

  select id into _owner
    from public.profiles
   where (lower(username) = _h or lower(coalesce(subdomain_alias, '')) = _h)
     and id <> _user_id
   limit 1;
  if _owner is not null then
    raise exception 'handle_taken: % is al in gebruik', _h using errcode = 'unique_violation';
  end if;

  if to_regclass('public.alias_profiles') is not null then
    execute 'select user_id from public.alias_profiles where lower(handle) = $1 and user_id <> $2 limit 1'
      into _owner using _h, _user_id;
    if _owner is not null then
      raise exception 'handle_taken: % is al in gebruik', _h using errcode = 'unique_violation';
    end if;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.assign_badge_serial_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.serial_number is null then
    select coalesce(max(serial_number), 0) + 1
      into new.serial_number
      from public.user_badges
     where badge_id = new.badge_id;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_referral(p_referrer text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  inviter uuid;
begin
  if auth.uid() is null then return; end if;
  select id into inviter from public.profiles where username = lower(p_referrer) limit 1;
  if inviter is null or inviter = auth.uid() then return; end if;
  update public.profiles set referred_by = inviter, updated_at = now()
    where id = auth.uid() and referred_by is null;
  if found then
    update public.profiles set referral_count = referral_count + 1 where id = inviter;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.contact_submissions_recent_count(_sender_hash text, _window_minutes integer DEFAULT 10)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::int
  from public.contact_submissions
  where _sender_hash is not null
    and sender_hash = _sender_hash
    and created_at > now() - make_interval(mins => greatest(_window_minutes, 1))
$function$;

CREATE OR REPLACE FUNCTION public.current_app_user_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
  select nullif(current_setting('app.current_user_id', true), '')::uuid
$function$;

CREATE OR REPLACE FUNCTION public.delete_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
begin
  if uid is null then raise exception 'Not signed in'; end if;
  delete from public.saved_qrs where user_id = uid;
  delete from public.tracked_qrs where user_id = uid;
  delete from public.api_keys where user_id = uid;
  delete from public.custom_domains where user_id = uid;
  delete from public.notifications where user_id = uid;
  delete from public.user_badges where user_id = uid;
  delete from public.profiles where id = uid;
end;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_short_link_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  is_verified boolean;
  per_hour int;
  max_total int;
  recent int;
  total int;
begin
  if new.user_id is null then
    raise exception 'RATE_LIMIT_SHORT_LINKS: short links need an owner';
  end if;

  select coalesce(p.verified, false) or coalesce(p.is_paid, false)
           or coalesce(p.is_early_believer, false)
    into is_verified
    from public.profiles p
   where p.id = new.user_id;

  if coalesce(is_verified, false) then
    per_hour := 60;
    max_total := 1000;
  else
    per_hour := 10;
    max_total := 25;
  end if;

  select count(*) into recent
    from public.tracked_qrs q
   where q.user_id = new.user_id
     and q.created_at > now() - interval '1 hour';

  if recent >= per_hour then
    raise exception 'RATE_LIMIT_SHORT_LINKS: too many new short links in the last hour';
  end if;

  select count(*) into total
    from public.tracked_qrs q
   where q.user_id = new.user_id;

  if total >= max_total then
    raise exception 'RATE_LIMIT_SHORT_LINKS: short link quota reached';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.generate_unique_handle(_seed text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  base text;
  candidate text;
  i int := 0;
begin
  base := regexp_replace(lower(coalesce(_seed, 'member')), '[^a-z0-9]+', '', 'g');
  if length(base) < 3 then base := base || 'member'; end if;
  base := left(base, 20);
  candidate := base;
  while not public.is_handle_available(candidate) loop
    i := i + 1;
    candidate := left(base, 20) || i::text;
    exit when i > 9999;
  end loop;
  return candidate;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_account()
 RETURNS TABLE(id uuid, email text, username text, display_name text, avatar_url text, tier text, status text, verified boolean, verified_at timestamp with time zone, is_early_believer boolean, is_paid boolean, show_email_publicly boolean, forwarding_email text, forwarding_email_verified boolean, bluesky_did text, roles app_role[])
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    p.id,
    p.email,
    p.username,
    p.display_name,
    p.avatar_url,
    p.tier,
    p.status,
    p.verified,
    p.verified_at,
    p.is_early_believer,
    p.is_paid,
    p.show_email_publicly,
    p.forwarding_email,
    p.forwarding_email_verified,
    p.bluesky_did,
    coalesce(array_agg(ur.role order by ur.role) filter (where ur.role is not null), '{}'::public.app_role[]) as roles
  from public.profiles p
  left join public.user_roles ur on ur.user_id = p.id
  where p.id = auth.uid()
  group by p.id;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_profile()
 RETURNS profiles
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select p.* from public.profiles p where p.id = auth.uid() limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.get_public_profile(_username text)
 RETURNS TABLE(id uuid, username text, display_name text, tagline text, bio text, avatar_url text, favicon_url text, theme text, card_style text, blocks jsonb, business_info jsonb, tier text, status text, verified boolean, verified_at timestamp with time zone, is_early_believer boolean, is_suspended boolean, is_banned boolean, subdomain_enabled boolean, custom_domain text, bluesky_did text, created_at timestamp with time zone, show_email_publicly boolean, forwarding_email text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    p.id, p.username, p.display_name, p.tagline, p.bio, p.avatar_url, p.favicon_url,
    p.theme, p.card_style, p.blocks, p.business_info, p.tier, p.status, p.verified,
    p.verified_at, p.is_early_believer, p.is_suspended, p.is_banned,
    p.subdomain_enabled, p.custom_domain, p.bluesky_did, p.created_at,
    p.show_email_publicly,
    case when p.show_email_publicly then p.forwarding_email else null end
  from public.profiles p
  where p.username = lower(_username)
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.grant_early_verified_promo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.verified and not coalesce(old.verified, false) then
    new.is_early_verified := true;
    insert into public.entitlement_overrides (scope_type, scope_id, entitlement_key, value, granted_by)
    values ('user', new.id, 'PRO_FOR_LIFE', 'true', 'early_verified_promo'),
           ('user', new.id, 'INCLUDED_PLUS_WORKSPACE', '1', 'early_verified_promo')
    on conflict (scope_type, scope_id, entitlement_key) do nothing;
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.grant_signup_badges(_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.user_badges (user_id, badge_id)
  select _user_id, b.id from public.badges b where b.slug in ('early-believer','member')
  on conflict (user_id, badge_id) do nothing;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.profiles (id, email, display_name, created_at, updated_at)
  values (
    new.id,
    new.email,
    nullif(new.user_metadata ->> 'full_name', ''),
    now(),
    now()
  )
  on conflict (id) do nothing;
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select _user_id = auth.uid()
    and exists (
      select 1
      from public.user_roles
      where user_id = _user_id
        and role = _role
    )
$function$;

CREATE OR REPLACE FUNCTION public.identity_verifications_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if old.is_verified and current_user = 'rout_app' and (
       new.is_verified is distinct from old.is_verified
    or new.verified_real_name is distinct from old.verified_real_name
    or new.unique_human_id is distinct from old.unique_human_id
    or new.verification_provider is distinct from old.verification_provider) then
    raise exception 'identity_immutable' using errcode = '42501';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.is_handle_available(_username text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select lower(_username) ~ '^[a-z0-9](?:[a-z0-9._-]{0,30}[a-z0-9])?$'
    and not exists (select 1 from public.profiles p where p.username = lower(_username))
    and not exists (select 1 from public.reserved_handles r where r.handle = lower(_username));
$function$;

CREATE OR REPLACE FUNCTION public.log_qr_scan(_tracked_qr_id uuid, _device text DEFAULT NULL::text, _country text DEFAULT NULL::text, _browser text DEFAULT NULL::text, _os text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare recent int;
begin
  if _tracked_qr_id is null then return; end if;

  select count(*) into recent
    from public.qr_scans
   where tracked_qr_id = _tracked_qr_id
     and scanned_at > now() - interval '1 minute';

  if recent >= 60 then return; end if;

  insert into public.qr_scans (tracked_qr_id, device, country, browser, os)
  values (_tracked_qr_id, left(_device, 20), left(_country, 2), left(_browser, 20), left(_os, 20));
end;
$function$;

CREATE OR REPLACE FUNCTION public.manage_short_link(_token text, _action text, _target_url text DEFAULT NULL::text, _is_active boolean DEFAULT NULL::boolean, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _slug text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  row public.tracked_qrs;
begin
  select * into row from public.tracked_qrs where dashboard_token = _token limit 1;
  if row.id is null then
    raise exception 'Dashboard not found';
  end if;

  if _action = 'update_target' then
    if _target_url is null or length(_target_url) < 3 then
      raise exception 'Invalid target url';
    end if;
    update public.tracked_qrs set target_url = _target_url, updated_at = now() where id = row.id;
  elsif _action = 'set_active' then
    update public.tracked_qrs set is_active = coalesce(_is_active, true), updated_at = now() where id = row.id;
  elsif _action = 'set_expiry' then
    update public.tracked_qrs set expires_at = _expires_at, updated_at = now() where id = row.id;
  elsif _action = 'regenerate_slug' then
    if _slug is null then raise exception 'Missing slug'; end if;
    update public.tracked_qrs set slug = lower(_slug), updated_at = now() where id = row.id;
  elsif _action = 'delete' then
    delete from public.tracked_qrs where id = row.id;
  else
    raise exception 'Unknown action %', _action;
  end if;

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.profiles_handle_namespace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.username is distinct from coalesce(old.username, null) then
    perform public.assert_handle_namespace_free(new.username, new.id);
  end if;
  if new.subdomain_alias is distinct from coalesce(old.subdomain_alias, null) then
    perform public.assert_handle_namespace_free(new.subdomain_alias, new.id);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_profile_draft(p_user_id uuid, p_space text, p_expected_revision bigint)
 RETURNS TABLE(revision bigint, published_revision bigint, published_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb;
  v_revision bigint;
begin
  select d.payload, d.revision into v_payload, v_revision
    from public.profile_drafts d
   where d.user_id = p_user_id and d.space = p_space
   for update;

  if v_payload is null or v_revision <> p_expected_revision then
    raise exception 'draft_conflict';
  end if;

  if p_space = 'verified' then
    update public.profiles set
      username = v_payload->>'username',
      display_name = nullif(v_payload->>'displayName', ''),
      tagline = nullif(v_payload->>'tagline', ''),
      avatar_url = nullif(v_payload->>'avatarUrl', ''),
      favicon_url = nullif(v_payload->>'faviconUrl', ''),
      theme = coalesce(nullif(v_payload->>'theme', ''), 'noir'),
      card_style = coalesce(nullif(v_payload->>'cardStyle', ''), 'bordered'),
      blocks = coalesce(v_payload->'blocks', '[]'::jsonb),
      display_prefs = coalesce(v_payload->'displayPrefs', '{}'::jsonb),
      updated_at = now()
    where id = p_user_id;
    if not found then raise exception 'profile_not_found'; end if;
  elsif p_space = 'alias' then
    update public.alias_profiles set
      handle = v_payload->>'username',
      display_name = nullif(v_payload->>'displayName', ''),
      tagline = nullif(v_payload->>'tagline', ''),
      avatar_url = nullif(v_payload->>'avatarUrl', ''),
      favicon_url = nullif(v_payload->>'faviconUrl', ''),
      theme = coalesce(nullif(v_payload->>'theme', ''), 'noir'),
      card_style = coalesce(nullif(v_payload->>'cardStyle', ''), 'bordered'),
      blocks = coalesce(v_payload->'blocks', '[]'::jsonb),
      display_prefs = coalesce(v_payload->'displayPrefs', '{}'::jsonb),
      updated_at = now()
    where user_id = p_user_id;
    if not found then raise exception 'profile_not_found'; end if;
  else
    raise exception 'draft_space_invalid';
  end if;

  update public.profile_drafts d
     set published_revision = d.revision, published_at = now(), updated_at = now()
   where d.user_id = p_user_id and d.space = p_space;

  return query
    select d.revision, d.published_revision, d.published_at
      from public.profile_drafts d
     where d.user_id = p_user_id and d.space = p_space;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_short_link(_slug text)
 RETURNS TABLE(id uuid, status text, target_url text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select q.id,
    case
      when not q.is_active then 'disabled'
      when q.expires_at is not null and q.expires_at < now() then 'expired'
      else 'ok'
    end as status,
    q.target_url
  from public.tracked_qrs q
  where q.slug = lower(_slug)
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.save_profile_draft(p_user_id uuid, p_space text, p_payload jsonb, p_expected_revision bigint)
 RETURNS TABLE(revision bigint, published_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_current bigint;
begin
  if p_space not in ('verified', 'alias') then
    raise exception 'draft_space_invalid';
  end if;

  select d.revision into v_current
    from public.profile_drafts d
   where d.user_id = p_user_id and d.space = p_space
   for update;

  if v_current is null then
    if p_expected_revision <> 0 then raise exception 'draft_conflict'; end if;
    insert into public.profile_drafts (user_id, space, payload, revision)
    values (p_user_id, p_space, p_payload, 1);
  else
    if v_current <> p_expected_revision then raise exception 'draft_conflict'; end if;
    update public.profile_drafts d
       set payload = p_payload, revision = d.revision + 1, updated_at = now()
     where d.user_id = p_user_id and d.space = p_space;
  end if;

  return query
    select d.revision, d.published_revision
      from public.profile_drafts d
     where d.user_id = p_user_id and d.space = p_space;
end;
$function$;

CREATE OR REPLACE FUNCTION public.seed_demo_content(_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.links (profile_id, title, url, position)
  select _user_id, 'My website', 'https://example.com', 0
  where exists (select 1 from public.profiles where id = _user_id)
    and not exists (select 1 from public.links where profile_id = _user_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.short_link_stats(_token text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when q.id is null then null else jsonb_build_object(
    'qr', to_jsonb(q),
    'scans', coalesce((
      select jsonb_agg(jsonb_build_object(
        'scanned_at', s.scanned_at, 'country', s.country,
        'device', s.device, 'browser', s.browser, 'os', s.os
      ) order by s.scanned_at desc)
      from public.qr_scans s where s.tracked_qr_id = q.id
    ), '[]'::jsonb)
  ) end
  from public.tracked_qrs q
  where q.dashboard_token = _token
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.signin_guard_record(_identity_hash text, _success boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.signin_throttle; new_failures int; lock_for interval;
begin
  if _identity_hash is null or length(_identity_hash) not between 16 and 128 then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  if _success then
    delete from public.signin_throttle where identity_hash = _identity_hash;
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  select * into r from public.signin_throttle where identity_hash = _identity_hash for update;

  if r.identity_hash is null or r.window_started_at < now() - interval '15 minutes' then
    insert into public.signin_throttle (identity_hash, failures, window_started_at, locked_until)
    values (_identity_hash, 1, now(), null)
    on conflict (identity_hash) do update
      set failures = 1, window_started_at = now(), locked_until = null;
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  new_failures := r.failures + 1;
  lock_for := case
    when new_failures >= 10 then interval '15 minutes'
    when new_failures >= 7 then interval '5 minutes'
    when new_failures >= 5 then interval '1 minute'
    else null end;

  update public.signin_throttle
     set failures = new_failures,
         locked_until = case when lock_for is null then null else now() + lock_for end
   where identity_hash = _identity_hash;

  delete from public.signin_throttle
   where window_started_at < now() - interval '1 day'
     and (locked_until is null or locked_until < now());

  if lock_for is null then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;
  return jsonb_build_object('locked', true,
    'retry_after', ceil(extract(epoch from lock_for))::int);
end;
$function$;

CREATE OR REPLACE FUNCTION public.signin_guard_status(_identity_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.signin_throttle;
begin
  select * into r from public.signin_throttle where identity_hash = _identity_hash;
  if r.identity_hash is null or r.locked_until is null or r.locked_until <= now() then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;
  return jsonb_build_object('locked', true,
    'retry_after', greatest(1, ceil(extract(epoch from (r.locked_until - now())))::int));
end;
$function$;

