CREATE OR REPLACE FUNCTION public.wallet_credit(_user_id uuid, _amount_cents integer, _kind text DEFAULT 'topup'::text, _description text DEFAULT NULL::text, _reference text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _balance integer;
begin
  if _amount_cents is null or _amount_cents <= 0 then
    raise exception 'wallet_credit: amount must be positive';
  end if;
  if _kind not in ('topup', 'refund', 'adjustment') then
    raise exception 'wallet_credit: invalid kind %', _kind;
  end if;

  insert into public.wallets (user_id) values (_user_id)
  on conflict (user_id) do nothing;

  -- Rijvergrendeling: parallelle webhooks wachten netjes op elkaar.
  select balance_cents into _balance
    from public.wallets where user_id = _user_id for update;

  begin
    insert into public.wallet_transactions
      (user_id, kind, amount_cents, description, reference)
    values (_user_id, _kind, _amount_cents, _description, _reference);
  exception when unique_violation then
    -- Zelfde Stripe-referentie: al geboekt, saldo ongewijzigd.
    return _balance;
  end;

  update public.wallets
     set balance_cents = balance_cents + _amount_cents
   where user_id = _user_id
   returning balance_cents into _balance;

  return _balance;
end $function$;

CREATE OR REPLACE FUNCTION public.wallet_debit(_user_id uuid, _amount_cents integer, _description text DEFAULT NULL::text, _reference text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _balance integer;
begin
  if _amount_cents is null or _amount_cents <= 0 then
    raise exception 'wallet_debit: amount must be positive';
  end if;

  insert into public.wallets (user_id) values (_user_id)
  on conflict (user_id) do nothing;

  select balance_cents into _balance
    from public.wallets where user_id = _user_id for update;

  if _balance is null or _balance < _amount_cents then
    return -1; -- onvoldoende saldo; niets geboekt
  end if;

  begin
    insert into public.wallet_transactions
      (user_id, kind, amount_cents, description, reference)
    values (_user_id, 'relay_fee', -_amount_cents, _description, _reference);
  exception when unique_violation then
    return _balance; -- deze periode al afgeschreven
  end;

  update public.wallets
     set balance_cents = balance_cents - _amount_cents
   where user_id = _user_id
   returning balance_cents into _balance;

  return _balance;
end $function$;

CREATE OR REPLACE FUNCTION public.wt_assert(ok boolean, msg text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
begin
  if not coalesce(ok, false) then
    raise exception '%', msg using errcode = 'P0001';
  end if;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION storage.foldername(name text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select string_to_array(regexp_replace(name, '/[^/]*$', ''), '/')
$function$;

create view public.profile_handles as
SELECT username
   FROM profiles
  WHERE username IS NOT NULL;

create view public.public_profiles as
SELECT id,
    username,
    display_name,
    tagline,
    bio,
    avatar_url,
    favicon_url,
    theme,
    card_style,
    blocks,
    business_info,
    tier,
    status,
    verified,
    verified_at,
    is_early_believer,
    is_suspended,
    is_banned,
    subdomain_enabled,
    custom_domain,
    bluesky_did,
    created_at,
    show_email_publicly,
    NULL::text AS forwarding_email
   FROM profiles
  WHERE username IS NOT NULL;

create view auth.users as
SELECT id,
    email,
    created_at,
    user_metadata AS raw_user_meta_data,
    app_metadata AS raw_app_meta_data,
    email_confirmed_at,
    last_sign_in_at,
    updated_at
   FROM users;

alter table neon_auth.account alter column id set default gen_random_uuid();
alter table neon_auth.account alter column "createdAt" set default CURRENT_TIMESTAMP;
alter table neon_auth.invitation alter column id set default gen_random_uuid();
alter table neon_auth.invitation alter column "createdAt" set default CURRENT_TIMESTAMP;
alter table neon_auth.jwks alter column id set default gen_random_uuid();
alter table neon_auth.member alter column id set default gen_random_uuid();
alter table neon_auth.organization alter column id set default gen_random_uuid();
alter table neon_auth.passkey alter column "createdAt" set default now();
alter table neon_auth.project_config alter column id set default gen_random_uuid();
