alter table public.bookings add constraint bookings_no_overlap EXCLUDE USING gist (host_user_id WITH =, tstzrange(block_start_utc, block_end_utc, '[)'::text) WITH &&) WHERE (((status = ANY (ARRAY['held'::text, 'pending_payment'::text, 'requested'::text, 'confirmed'::text])) AND (NOT shared_slot)));
alter table public.ambient_weather_cache add constraint ambient_weather_cache_state_check CHECK ((state = ANY (ARRAY['Clear'::text, 'Rain'::text, 'Snow'::text, 'Thunderstorm'::text, 'Clouds/Fog'::text])));
alter table public.ambient_weather_locations add constraint ambient_weather_locations_city_check CHECK (((city IS NULL) OR ((length(city) >= 2) AND (length(city) <= 80))));
alter table public.approved_handles add constraint approved_handles_kind_check CHECK ((request_kind = ANY (ARRAY['influencer'::text, 'business'::text])));
alter table public.approved_handles add constraint approved_handles_status_check CHECK ((status = ANY (ARRAY['approved'::text, 'claimed'::text, 'void'::text])));
alter table public.auth_tokens add constraint auth_tokens_purpose_check CHECK ((purpose = ANY (ARRAY['magic_link'::text, 'password_reset'::text, 'email_confirm'::text, 'email_change'::text, 'email_code'::text])));
alter table public.availability_overrides add constraint availability_overrides_check CHECK ((end_utc > start_utc));
alter table public.availability_overrides add constraint availability_overrides_kind_check CHECK ((kind = ANY (ARRAY['free'::text, 'busy'::text])));
alter table public.availability_rules add constraint availability_rules_check CHECK ((end_minute > start_minute));
alter table public.availability_rules add constraint availability_rules_end_minute_check CHECK (((end_minute >= 1) AND (end_minute <= 1440)));
alter table public.availability_rules add constraint availability_rules_start_minute_check CHECK (((start_minute >= 0) AND (start_minute <= 1439)));
alter table public.availability_rules add constraint availability_rules_weekday_check CHECK (((weekday >= 0) AND (weekday <= 6)));
alter table public.badge_claim_links add constraint badge_claim_links_max_chk CHECK (((max_claims IS NULL) OR ((max_claims >= 1) AND (max_claims <= 100000))));
alter table public.badge_claim_links add constraint badge_claim_links_token_chk CHECK ((token ~ '^stamp_[a-z0-9]{8,32}$'::text));
alter table public.booking_event_types add constraint booking_event_types_buffer_after_minutes_check CHECK (((buffer_after_minutes >= 0) AND (buffer_after_minutes <= 240)));
alter table public.booking_event_types add constraint booking_event_types_buffer_before_minutes_check CHECK (((buffer_before_minutes >= 0) AND (buffer_before_minutes <= 240)));
alter table public.booking_event_types add constraint booking_event_types_capacity CHECK (((resource_capacity >= 1) AND (resource_capacity <= 100)));
alter table public.booking_event_types add constraint booking_event_types_confirmation_mode_check CHECK ((confirmation_mode = ANY (ARRAY['instant'::text, 'request'::text])));
alter table public.booking_event_types add constraint booking_event_types_currency_check CHECK ((currency ~ '^[a-z]{3}$'::text));
alter table public.booking_event_types add constraint booking_event_types_custom_fields_array CHECK (((jsonb_typeof(custom_fields) = 'array'::text) AND (jsonb_array_length(custom_fields) <= 20)));
alter table public.booking_event_types add constraint booking_event_types_description_check CHECK ((length(description) <= 2000));
alter table public.booking_event_types add constraint booking_event_types_duration_minutes_check CHECK ((((duration_minutes >= 5) AND (duration_minutes <= 480)) AND ((duration_minutes % 5) = 0)));
alter table public.booking_event_types add constraint booking_event_types_location_kind_check CHECK ((location_kind = ANY (ARRAY['video'::text, 'address'::text, 'phone'::text])));
alter table public.booking_event_types add constraint booking_event_types_location_value_check CHECK ((length(location_value) <= 500));
alter table public.booking_event_types add constraint booking_event_types_max_days_ahead_check CHECK (((max_days_ahead >= 1) AND (max_days_ahead <= 365)));
